import { useNavigate } from '@tanstack/react-router'

import toast from '@/lib/toast'

// Components, UI
import { Upload, Camera, DollarSign } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Header } from '@/components/ui/Header'
import { Separator } from '@/components/ui/separator'
import { Textarea } from '@/components/ui/textarea'
import { Progress } from '@/components/ui/progress'
import { Input } from '@/components/ui/input'
import {
  CheckSign,
  DataInput,
  DataSelection,
  VehicleCategories,
  VehicleAttributes,
  VehicleFeatures,
} from '@/components/rent-my-car/Form'
import {
  StepCircle,
  StepTitle,
  StepSubtitle,
  SectionTitle,
  ItemTitle,
  DailyRateCard,
  PreviousStepButton,
  NextStepButton,
  PublishButton,
  ImagePreview,
} from '@/components/rent-my-car/ui'

// Methods
import { getBrandsForCategory } from '@/types/vehicle-data'

//Hooks
import { useCategory } from '@/hooks/useCategory'
import { useUpdateVehicle } from '@/hooks/useUpdateVehicle'
import { useAttribute } from '@/hooks/useAttribute'
import { useFeature } from '@/hooks/useFeature'
import { useCreateVehicle } from '@/hooks/useCreateVehicle'
import type { Feature, FileWithURL } from '@/types/vehicle'
import {
  useAddAttributesToVehicle,
  type AddAttributesPayload,
} from '@/hooks/useAddAttributesToVehicle'
import { useUploadImages } from '@/hooks/useUploadImages'
//import { useAddFeaturesToVehicle } from '@/hooks/useAddFeaturesToVehicle'

export const RentMyCar = () => {
  // Variables
  const navigate = useNavigate()

  useEffect(() => {
    const handleBeforeUnload = (event: BeforeUnloadEvent) => {
      event.preventDefault()
      event.returnValue = ''
    }

    window.addEventListener('beforeunload', handleBeforeUnload)

    return () => {
      window.removeEventListener('beforeunload', handleBeforeUnload)
    }
  }, [])

  // Global
  const MIN_STEP = 1
  const MAX_STEP = 3
  const MIN_YEAR = 1970
  const MAX_YEAR = 2025

  // Hooks API
  const { mutateAsync: createVehicle } = useCreateVehicle()
  const { mutateAsync: updateVehicle } = useUpdateVehicle()
  const { mutateAsync: uploadImages } = useUploadImages()
  const [carCategoryId, setCarCategoryId] = useState(-1)
  const { data: categoryAttributes } = useAttribute(carCategoryId)
  const [createdVehicle, setCreatedVehicle] = useState<any>(null)
  const vehicleDocumentId = createdVehicle
  const { mutateAsync: addAttributes } = useAddAttributesToVehicle()

  // Navigation
  const [step, setStep] = useState(1)

  const canContinue = () => {
    if (!getBrandsForCategory(carType)) return false
    switch (step) {
      case 1:
        return carType !== '' && carBrand !== '' && carModel !== '' && carYear !== ''
      case 2:
        return imagesURL.length >= 3 && validPricePerDay() && carDescription !== ''
      case 3:
        return (
          Object.keys(categoryAttributes ?? []).length === Object.keys(selectedAttributes).length &&
          carInsurance &&
          carState &&
          termsAndConditions
        )
      default:
        return false
    }
  }

  const moveStep = async (newStep: number) => {
    // Si estamos saliendo del paso 1 hacia el paso 2, creamos o actualizamos el vehículo
    if (step === 1 && newStep === 2) {
      try {
        if (createdVehicle) {
          // Update existing vehicle
          await updateVehicle({
            vehicleDocumentId: createdVehicle,
            updateData: {
              brand: carBrand,
              model: carModel,
              year: parseInt(carYear),
              price: parseInt(pricePerDay),
              description: carDescription,
              rules: carRules !== '' ? carRules : undefined,
              category_id: {
                connect: carCategoryId,
              },
            },
          })
        } else {
          // Create new vehicle
          const vehicle = await createVehicle({
            brand: carBrand,
            model: carModel,
            year: parseInt(carYear),
            price: pricePerDay ? parseInt(pricePerDay) : 0,
            description: carDescription,
            rules: carRules !== '' ? carRules : undefined,
            current_status: 'paused',
            category_id: {
              connect: carCategoryId,
            },
          })
          setCreatedVehicle(vehicle.documentId)
        }
        setStep(newStep)
      } catch (err: any) {
        toast.error(err.message || 'Error creating/updating vehicle')
      }
    } else if (step === 2 && newStep === 3) {
      try {
        await updateVehicle({
          vehicleDocumentId: createdVehicle,
          updateData: {
            price: parseInt(pricePerDay),
            description: carDescription,
            rules: carRules !== '' ? carRules : undefined,
          },
        })

        setStep(newStep)
      } catch (err: any) {
        toast.error(err.message || 'Error updating vehicle')
      }
    } else {
      try {
        await updateVehicle({
          vehicleDocumentId: createdVehicle,
          updateData: {
            features: {
              set: selectedFeatures,
            },
          },
        })

        setStep(newStep)
      } catch (err: any) {
        toast.error(err.message || 'Error updating vehicle')
      }
    }
  }

  const getProgress = () => {
    return (100 / 3) * step
  }

  // VEHICLE DATA TO SEND TO API

  // Step 1: Car data
  const [carType, setCarTypeRaw] = useState('')
  const setCarType = (type: string) => {
    setCarTypeRaw(type.toLowerCase())
    setCarBrand('')
  }
  const { data: categories } = useCategory()

  const [carBrand, setCarBrand] = useState('')
  const [carModel, setCarModel] = useState('')
  const [carYear, setCarYear] = useState('')

  // Step 2: Price data
  const [pricePerDay, setPricePerDay] = useState('')

  const [carDescription, setCarDescription] = useState('')
  const [carRules, setCarRules] = useState('')

  // Step 3: Attributes and features
  const [selectedAttributes, setSelectedAttributes] = useState<Record<string, string>>({})

  const setAttribute = useCallback((targetAttribute: string, selectedValue: string) => {
    // Usa la función de actualización de useState que recibe el estado anterior (prev)
    setSelectedAttributes(prev => ({
      // Mantenemos las selecciones previas (...prev)
      ...prev,
      // Sobrescribimos o añadimos el nuevo atributo seleccionado
      [targetAttribute]: selectedValue,
    }))
  }, [])

  const { data: features } = useFeature(carCategoryId)
  const [selectedFeatures, setSelectedFeatures] = useState<number[]>([])

  const setFeature = (targetFeature: Feature) => {
    setSelectedFeatures(features => {
      const exists = features.some(featureID => featureID === targetFeature.id)
      if (exists) {
        // Delete feature
        return features.filter(featureID => featureID !== targetFeature.id)
      } else {
        // Add feature
        return [...features, targetFeature.id]
      }
    })
  }

  const publishAttributes = useCallback(async () => {
    if (!vehicleDocumentId) {
      throw new Error('Vehicle ID is missing for attribute assignment.')
    }

    const attributePromises = Object.keys(selectedAttributes).map(attributeIdString => {
      const attributeId = parseInt(attributeIdString)
      const attributeOptionId = parseInt(selectedAttributes[attributeIdString])

      const payload: AddAttributesPayload = {
        vehicle_id: vehicleDocumentId,
        attribute_id: attributeId,
        attribute_option_id: attributeOptionId,
      }
      return addAttributes(payload)
    })

    const createdAttributesArray = await Promise.all(attributePromises)

    const newlyCreatedAttributeIds = createdAttributesArray
      .map((response: any) => response.data.id)
      .filter(id => id !== undefined)

    if (newlyCreatedAttributeIds.length > 0) {
      await updateVehicle({
        vehicleDocumentId: createdVehicle,
        updateData: {
          attributes: {
            set: newlyCreatedAttributeIds,
          },
        },
      })
    }
  }, [vehicleDocumentId, selectedAttributes, addAttributes, updateVehicle, createdVehicle])

  const [carInsurance, setCarInsurance] = useState(false)
  const [carState, setCarState] = useState(false)
  const [termsAndConditions, setTermsAndConditions] = useState(false)

  // Photos
  //const [images, setImages] = useState<File[]>([]) // Photos list
  const [imagesURL, setImagesURL] = useState<FileWithURL[]>([])

  // Photo management

  const fileInputRef = useRef<HTMLInputElement>(null)

  const openFileExplorer = () => fileInputRef.current?.click()

  const handleFiles = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!e.target.files) return // Avoid null errors (cancel, empty list, etc)

    const newFiles = Array.from(e.target.files).map(file => ({
      file: file,
      url: URL.createObjectURL(file),
    }))

    setImagesURL(prev => [...prev, ...newFiles])
  }

  const publishImages = useCallback(async () => {
    if (!vehicleDocumentId) {
      throw new Error('Vehicle ID is missing for image assignment.')
    }

    const formData = new FormData()

    imagesURL.forEach(file => {
      formData.append('files', file.file)
    })

    const uploadedImages = await uploadImages(formData)

    const imageIds = uploadedImages.map((img: any) => img.id)

    await updateVehicle({
      vehicleDocumentId: createdVehicle,
      updateData: {
        images: {
          connect: imageIds,
        },
      },
    })
  }, [vehicleDocumentId, imagesURL, uploadImages, updateVehicle, createdVehicle])

  // Utils

  const validPricePerDay = () => {
    return /^\d+$/.test(pricePerDay.toString())
    // Check that price per day is an integer
  }

  return (
    <div className="min-h-screen flex flex-col">
      <Header />

      {/** Step header */}
      <header className="mt-16 px-4 py-6 flex items-center justify-center border-b">
        <div className="w-[900px] min-w-sm">
          <div className="grid grid-cols-2">
            <div className="flex justify-start text-base">Step {step} of 3</div>
            <div className="flex justify-end text-base text-gray-700">
              {getProgress().toFixed()}% completed
            </div>
          </div>
          <div className="flex items-center justify-center mt-4">
            <div className="w-full">
              <Progress value={getProgress()} />
            </div>
          </div>
          <div className="grid grid-cols-3 w-full text-xs font-semibold">
            {StepCircle(step, 'Vehicle Information', 1)}
            {StepCircle(step, 'Photos & Pricing', 2)}
            {StepCircle(step, 'Attributes & Features', 3)}
          </div>
        </div>
      </header>

      {/** Content */}
      <div className="flex-1 flex items-start justify-center p-20 bg-gray-50">
        <Card className="w-[900px] min-w-sm">
          {/** Basic vehicle information */}
          {step === 1 ? (
            <>
              <CardHeader>
                <CardTitle>{StepTitle('Vehicle Information')}</CardTitle>
                {StepSubtitle('Category, brand, model and basic details')}
              </CardHeader>
              <CardContent>
                {/** Category */}
                {SectionTitle('Vehicle Category')}

                {VehicleCategories(categories, carType, setCarType, setCarCategoryId)}
                {carType === '' ? (
                  <div></div>
                ) : (
                  <div className="flex flex-col gap-2">
                    {/** Information form */}
                    <Separator className="mt-6 mb-6" />
                    <div>{SectionTitle('Basic Information')}</div>
                    <div className="grid grid-cols-2 sm:grid-cols-1 md:grid-cols-2 gap-x-4">
                      {/** Brand */}
                      <div className="flex flex-col mt-3 mb-3 gap-1">
                        {ItemTitle('Brand')}
                        {DataSelection(
                          carBrand,
                          setCarBrand,
                          'Select brand',
                          getBrandsForCategory(carType.toLowerCase())
                        )}
                      </div>
                      {/** Model */}
                      <div className="flex flex-col mt-3 mb-3 gap-1">
                        {ItemTitle('Model')}
                        {DataInput(carModel, setCarModel, 'Ex: Corolla, Civic, etc.')}
                      </div>
                      {/** Car Year */}
                      <div className="flex flex-col mt-3 mb-3 gap-1">
                        {ItemTitle('Year')}
                        {DataSelection(
                          carYear,
                          setCarYear,
                          'Year',
                          Array.from({ length: MAX_YEAR - MIN_YEAR + 1 }, (_, i) =>
                            (MAX_YEAR - i).toString()
                          )
                        )}
                      </div>
                    </div>
                  </div>
                )}
              </CardContent>
            </>
          ) : step === 2 ? (
            <>
              {/** Photos & pricing */}
              <CardHeader>
                <CardTitle>{StepTitle('Photos & Pricing')}</CardTitle>
                {StepSubtitle('Images, price and rental conditions')}
              </CardHeader>
              <CardContent className="flex flex-col gap-2">
                {/** Photos */}
                <div>
                  <div>{SectionTitle('Vehicle Photos')}</div>

                  <div className="flex flex-col items-center gap-2 mt-2 p-8 border-2 border-gray-300 border-dashed rounded-lg">
                    <Camera className="text-gray-400 w-7 h-7" />
                    <div>Upload photos of your vehicle</div>
                    <div className="text-sm text-gray-600">
                      Add at least 3 photos. The first photo will be the main image.
                    </div>
                    <Button
                      onClick={() => {
                        openFileExplorer()
                      }}
                    >
                      <Upload />
                      Select photos
                    </Button>
                    <input
                      id="file"
                      name="file"
                      type="file"
                      multiple
                      accept="image/*"
                      ref={fileInputRef}
                      onChange={handleFiles}
                      className="hidden"
                    />
                  </div>

                  <div>{ImagePreview(imagesURL, setImagesURL)}</div>
                </div>
                <Separator className="mt-6 mb-6" />
                {/** Daily Rate */}
                <div>
                  {SectionTitle('Daily Rate')}
                  <div className="mt-3 mb-3">{ItemTitle('Price per day')}</div>
                  <div className="relative">
                    <DollarSign className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-5 h-5" />
                    <Input
                      id="number"
                      name="number"
                      type="number"
                      step="1"
                      value={pricePerDay}
                      onChange={e => setPricePerDay(e.target.value)}
                      placeholder="Price in US dollars"
                      className="pl-10"
                    />
                  </div>
                  {DailyRateCard(pricePerDay)}
                </div>
                <Separator className="mt-6 mb-6" />
                {/** Rental info */}
                <div className="flex flex-col gap-6">
                  <div className="flex flex-col gap-2">
                    {ItemTitle('Vehicle description')}
                    <Textarea
                      id="description"
                      className="focus-visible:ring-[#03A7B9] focus-visible:ring-2 focus:ring-offset-2 transition-none rounded-sm"
                      placeholder="Describe your vehicle, its condition, special features, etc."
                      value={carDescription}
                      onChange={e => setCarDescription(e.target.value)}
                    />
                  </div>
                  <div className="flex flex-col gap-2">
                    {ItemTitle('Rental Rules')}
                    <Textarea
                      id="rules"
                      className="focus-visible:ring-[#03A7B9] focus-visible:ring-2 focus:ring-offset-2 transition-none rounded-sm"
                      placeholder="Ex: No smoking, return with the same fuel level, maximum 200 km per day, etc."
                      value={carRules}
                      onChange={e => setCarRules(e.target.value)}
                    />
                  </div>
                </div>
              </CardContent>
            </>
          ) : step === 3 ? (
            <>
              {/** Attributes and features */}
              <CardHeader>
                <CardTitle>{StepTitle('Attributes & Features')}</CardTitle>
                {StepSubtitle('Vehicle specifications and equipment')}
              </CardHeader>
              <CardContent className="flex flex-col gap-2">
                {SectionTitle('Vehicle Attributes')}

                <VehicleAttributes
                  categoryId={carCategoryId}
                  selectedAttributes={selectedAttributes}
                  setAttribute={setAttribute}
                ></VehicleAttributes>
                {/*VehicleAttributes(carCategoryId, selectedAttributes, setAttribute)*/}
                <Separator className="mt-6 mb-6" />

                {SectionTitle('Vehicle Features')}
                {VehicleFeatures(carCategoryId, selectedFeatures, features ?? [], setFeature)}
                <Separator className="mt-6 mb-6" />
                {/** Checklist */}
                <div>
                  {SectionTitle('Confirmation')}
                  <div className="flex flex-col gap-1 mt-3 mb-3">
                    {CheckSign(
                      'I confirm that the vehicle has valid insurance',
                      carInsurance,
                      setCarInsurance
                    )}
                    {CheckSign(
                      'The vehicle is in good condition and up to date with maintenance',
                      carState,
                      setCarState
                    )}
                    {CheckSign(
                      'I accept the terms and conditions of PickNDrive',
                      termsAndConditions,
                      setTermsAndConditions
                    )}
                  </div>
                </div>
              </CardContent>
            </>
          ) : (
            <div>Something went wrong</div>
          )}
          <CardContent>
            {/** Step navigation */}
            <div className="flex items-center justify-between mt-12">
              {step == MIN_STEP ? <div></div> : <>{PreviousStepButton(step, moveStep)}</>}
              {step === MAX_STEP ? (
                <>
                  {PublishButton(
                    {
                      vehicleDocumentId: createdVehicle,
                      updateData: {
                        current_status: 'active',
                        features: {
                          set: selectedFeatures,
                        },
                      },
                    },
                    updateVehicle,
                    publishAttributes,
                    publishImages,
                    canContinue(),
                    () => navigate({ to: '/profile', search: { tab: 'vehicles' } })
                  )}
                </>
              ) : (
                <>{NextStepButton(step, moveStep, canContinue())}</>
              )}
            </div>
          </CardContent>
        </Card>
      </div>
    </div>
  )
}
