} from '@/hooks/useAttributesWithOptions'

export const CategoryButton = (
  message: string,
  value: string,
  target: string,
  action: (type: string) => void,
  carCategoryId?: number,
  setCarCategoryId?: (id: number) => void
) => {
  const isActive = target === value.toLowerCase()
  return (
    <button
      className={cn(
        'w-full rounded-md p-4 h-14 flex items-center justify-center transition-colors cursor-pointer border text-base',
        isActive
          ? 'bg-[#CDFCFE] border-[#03A7B0] text-[#3EA7B0]'
          : 'bg-white border-gray-200 text-black'
      )}
      onClick={() => {
        action(value)
        setCarCategoryId?.(carCategoryId!)
      }}
    >
      {message}
    </button>
  )
}

export const FeatureBox = (
  feature: Feature,
  selectedFeatures: number[],
  setFeature: (feature: Feature) => void
) => {
  return (
    <Card
      className={cn(
        'flex flex-row p-3 cursor-pointer transition-colors rounded-md shadow-none border-1 hover:border-gray-300',
        selectedFeatures.includes(feature.id) ? 'bg-[#D2F9FB] border-[#03A7B9]' : 'bg-white'
      )}
      onClick={() => {
        setFeature(feature)
      }}
    >
      <Checkbox
        className="shadow-none cursor-pointer border-[#03A7B9]"
        checked={selectedFeatures.includes(feature.id)}
      />
      <div
        className={cn(
          'text-sm select-none',
          selectedFeatures.includes(feature.id) ? 'text-[#03A7B9]' : 'text-black'
        )}
      >
        {feature.name}
      </div>
    </Card>
  )
}

export const CheckSign = (message: string, value: boolean, action: (value: boolean) => void) => {
  return (
    <div className="flex items-center gap-x-2 select-none text-sm" onClick={() => action(!value)}>
      <Checkbox className="shadow-none cursor-pointer border-[#03A7B9]" checked={value} />
      {message}
    </div>
  )
}

export const DataInput = (
  value: string,
  onChange: (value: string) => void,
  placeholder: string,
  space: boolean = false
) => {
  return (
    <Input
      id="data-input"
      name="data-input"
      className={`relative rounded-sm p-5 focus-visible:ring-[#03A7B9] focus-visible:ring-2 focus:ring-offset-2 transition-none ${space ? 'pl-10' : ''}`}
      placeholder={placeholder}
      value={value}
      onChange={e => onChange(e.target.value)}
    />
  )
}

// Data selection where values displayed are not the same as the stored values
export const AttributeSelection = ({
  attribute,
  attributes,
  setAttribute,
}: {
  attribute: AttributeWithOptions
  attributes: Record<string, string>
  setAttribute: (target: string, value: string) => void
}) => {
  return (
    <Select
      value={attributes[attribute.id.toString()] || ''}
      onValueChange={value => setAttribute(attribute.id.toString(), value)}
    >
      <SelectTrigger className="w-full rounded-sm p-5 focusr:ring-offset-2">
        <SelectValue className="text-black" placeholder={'Select ' + attribute.attribute} />
      </SelectTrigger>
      <SelectContent>
        {attribute.options.map(option => (
          <SelectItem key={option.id} className="pl-7" value={option.id.toString()}>
            {option.value}
          </SelectItem>
        ))}
      </SelectContent>
    </Select>
  )
}

// Simple menu selection for strings
export const DataSelection = (
  value: string,
  onChange: (value: string) => void,
  placeholder: string,
  options: string[]
) => {
  return (
    <Select value={value} onValueChange={onChange}>
      <SelectTrigger className="w-full rounded-sm p-5 focusr:ring-offset-2">
        <SelectValue className="text-black" placeholder={placeholder} />
      </SelectTrigger>
      <SelectContent>
        {options.map(option => (
          <SelectItem key={option} className="pl-7" value={option}>
            {option}
          </SelectItem>
        ))}
      </SelectContent>
    </Select>
  )
}

export const VehicleCategories = (
  categories: Category[] | undefined,
  carType: string,
  setCarType: (type: string) => void,
  setCarCategoryId?: (id: number) => void
) => {
  return (
    <div className="grid grid-cols-3 sm:grid-cols-2 md:grid-cols-3 mt-4 gap-4">
      {Object.entries(categories ?? []).map(([, category]) => (
        <div key={category.id}>
          {CategoryButton(
            category.value,
            category.value,
            carType,
            setCarType,
            category.id,
            setCarCategoryId
          )}
        </div>
      ))}
    </div>
  )
}

const toSentenceCase = (str: string) => {
  if (!str) return ''
  return str.charAt(0).toUpperCase() + str.slice(1).toLowerCase()
}

export const VehicleAttributes = ({
  categoryId,
  selectedAttributes,
  setAttribute,
}: {
  categoryId: number
  selectedAttributes: Record<string, string>
  setAttribute: (attribute: string, optionID: string) => void
}) => {
  const { data: attributesWithOptions, isLoading, isError } = useAttributesWithOptions(categoryId)

  if (isLoading) {
    return <div className="p-4 text-gray-500">Cargando todos los datos...</div>
  }

  if (attributesWithOptions?.length === 0) {
    return <div className="p-4 text-gray-500">No attributes available for this category</div>
  }

  if (isError || !attributesWithOptions) {
    return <div className="p-4 text-red-500">Error while loading attributes</div>
  }

  return (
    <div className="grid grid-cols-1 sm:grid-cols-1 md:grid-cols-2 gap-6 mt-3 mb-3">
      {attributesWithOptions.map(attribute => (
        <div key={attribute.id} className="flex flex-col gap-2">
          {toSentenceCase(attribute.attribute)}
          <AttributeSelection
            attribute={attribute}
            attributes={selectedAttributes} // Mapa de selecciones
            setAttribute={setAttribute}
          ></AttributeSelection>
        </div>
      ))}
    </div>
  )
}

export const VehicleFeatures = (
  _categoryId: number,
  selectedFeatures: number[],
  categoryFeatures: Feature[],
  setFeature: (feature: Feature) => void
) => {
