import toast from 'react-hot-toast'
import type { FileWithURL } from '@/types/vehicle'

export const StepCircle = (step: number, message: string, forStep: number) => {
  return (
    <div className="flex justify-self-center justify-center items-center flex-col">
      {step < forStep ? (
        <div className="rounded-full bg-gray-200 text-gray-400 text-sm flex items-center justify-center mt-4 mb-2 w-8 h-8">
          {forStep}
        </div>
      ) : step == forStep ? (
        <div className="rounded-full border-2 border-primary text-primary text-sm flex items-center justify-center mt-4 mb-2 w-8 h-8 bg-[#D2F9FB]">
          {forStep}
        </div>
      ) : (
        <div className="rounded-full bg-primary text-white flex items-center justify-center mt-4 mb-2 w-8 h-8">
          <Check className="w-5 h-5" />
        </div>
      )}
      <div className={step >= forStep ? 'text-primary' : 'text-gray-400'}>{message}</div>
    </div>
  )
}

export const StepTitle = (message: string) => {
  return <div className="tracking-tight font-semibold text-2xl">{message}</div>
}

export const StepSubtitle = (message: string) => {
  return <div className="text-base text-gray-600">{message}</div>
}

export const SectionTitle = (message: string) => {
  return <div className="font-medium text-xl">{message}</div>
}

export const ItemTitle = (message: string) => {
  return <div className="text-md">{message}</div>
}

export const DailyRateCard = (pricePerDay: string) => {
  const price = parseInt(pricePerDay) || 0

  return (
    <Card className="mt-4 rate-info-box rounded-sm bg-[#D2F9FB] text-[#03A7B9] border-none shadow-none">
      <CardContent>
        <div className="font-semibold mb-2">Rate information</div>
        <div className="grid grid-cols-2">
          <div className="flex justify-start text">Your daily rate:</div>
          <div className="flex justify-end">${price}</div>
        </div>
        <div className="text-xs">
          Renters will contact you directly to arrange payment and pickup details.
        </div>
      </CardContent>
    </Card>
  )
}

export const PreviousStepButton = (currentStep: number, moveStep: (newStep: number) => void) => {
  return (
    <Button
      className={cn(
        'border-1 rounded-sm p-4 bg-white hover:bg-white',
        currentStep === 1 ? 'text-[#999999] border-[#EEEEEE]' : 'text-black border-[#DDDDDD]'
      )}
      onClick={() => {
        moveStep(currentStep - 1)
      }}
    >
      Previous
    </Button>
  )
}

export const NextStepButton = (
  currentStep: number,
  moveStep: (newStep: number) => void,
  canContinue: boolean
) => {
  return (
    <Button
      className={cn('rounded-sm p-4', canContinue ? 'bg-[#03A7B0]' : 'bg-[#81D3D7]')}
      onClick={() => (canContinue ? moveStep(currentStep + 1) : {})}
    >
      Next
    </Button>
  )
}

export const PublishButton = (
  data: UpdateVehiclePayload,
  publish: (data: UpdateVehiclePayload) => void,
  publishAttributes: () => void,
  publishImages: () => void,
  canContinue: boolean,
  onSuccess: () => void
) => {
  const handleClick = async () => {
    if (!canContinue) return

    try {
      await publishAttributes()
      await publishImages()
      await publish(data)

      toast.success('Vehicle published successfully')
      onSuccess()
    } catch (error: any) {
      toast.error(error.message || 'Failed to publish vehicle')
    }
  }

  return (
    <Button
      className={cn('rounded-sm p-4', canContinue ? 'bg-[#16A34A]' : 'bg-[#8AD1A4]')}
      onClick={handleClick}
      disabled={!canContinue}
    >
      Publish Vehicle
    </Button>
  )
}

export const deleteImage = (
  selectedImage: FileWithURL,
  setImagesURL: React.Dispatch<SetStateAction<FileWithURL[]>>
) => {
  URL.revokeObjectURL(selectedImage.url)

  setImagesURL(images => {
    return images.filter(image => image.url !== selectedImage.url)
  })
}

export const ImagePreview = (
  images: FileWithURL[],
  setImagesURL: React.Dispatch<SetStateAction<FileWithURL[]>>
) => {
  if (images.length === 0) return <></>
  return (
    <div className="grid grid-cols-4 sm:grid-cols-3 md:grid-cols-4 gap-4 mt-6">
      {images.map((image, i) => (
        <Card
          key={i}
          className="relative bg-cover bg-center w-full aspect-[233/100]"
          style={{ backgroundImage: `url(${image.url})` }}
        >
          <Button
            className="absolute top-1 right-1 w-6 h-6 p-1 flex items-center justify-center"
            variant="destructive"
            onClick={() => {
              deleteImage(image, setImagesURL)
            }}
          >
            <X className="text-white w-0.5 h-0.5" />
          </Button>
          {i === 0 ? ( // Main image
            <Badge className="absolute bottom-1 left-1 p-1 w-12 text-xs font-semibold flex items-center justify-center rounded-xl">
              Main
            </Badge>
          ) : (
            <></>
          )}
        </Card>
      ))}
    </div>
  )
}
